    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Uniform non-background lines divide the grid into matching panels.
    divider_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    divider_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    def panels(size, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    row_panels = panels(h, divider_rows)
    col_panels = panels(w, divider_cols)
    regions = [
        (r0, r1, c0, c1)
        for r0, r1 in row_panels
        for c0, c1 in col_panels
    ]

    # The panel containing the most non-background cells supplies the pattern.
    sr0, sr1, sc0, sc1 = max(
        regions,
        key=lambda p: sum(
            grid[r][c] != background
            for r in range(p[0], p[1])
            for c in range(p[2], p[3])
        )
    )
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]

    out = [row[:] for row in grid]
    for r0, r1 in row_panels:
        for c0, c1 in col_panels:
            if r1 - r0 == len(pattern) and c1 - c0 == len(pattern[0]):
                for i in range(len(pattern)):
                    for j in range(len(pattern[0])):
                        out[r0 + i][c0 + j] = pattern[i][j]
    return out
